#!/bin/bash
HOST="http://127.0.0.1:3000"
PASS=0; FAIL=0
run() {
  local url="$1"; local body="$2"; local name="$3"
  local code=$(curl -s -o /dev/null -w "%{http_code}" -X POST "$HOST$url" -H 'Content-Type: application/json' -d "$body")
  if [ "$code" = "200" ]; then echo "  PASS $name ($code)"; PASS=$((PASS+1));
  else echo "  FAIL $name ($code)"; FAIL=$((FAIL+1)); fi
}
echo "=== 101 CKD ==="
run "/api/nep_ckd/st" '{"gfr":45,"kidney_damage":true,"albuminuria":100,"stage":"g3a","dialysis_initiated":false}' "st"
run "/api/nep_ckd/alb" '{"alb_creat_ratio":50,"category":"a2","urine_collected":true,"confirmed":true,"first_morning":true}' "alb"
run "/api/nep_ckd/prog" '{"gfr_slope":-3,"baseline_gfr":60,"current_gfr":45,"rapid_decline":false,"referral_needed":true}' "prog"
run "/api/nep_ckd/bp" '{"sbp":135,"dbp":85,"ace_inhibitor":true,"ARB":false,"diuretic":true,"target_met":true}' "bp"
run "/api/nep_ckd/met" '{"bicarb":22,"potassium":4.5,"phosphate":1.2,"pth":80,"alkali_therapy":false,"phosphate_binder":false}' "met"
run "/api/nep_ckd/an" '{"hgb":10.5,"tsat":25,"esa_initiated":true,"iron_repletion":true,"target_hgb_met":true}' "an"
echo "=== 102 DIALYSIS ==="
