run "/api/nep_dial/pres" '{"duration_hours":4,"frequency_per_week":3,"dialysate_prescription":2,"individualized":true,"reviewed":true}' "pres"
echo "=== 103 AKI ==="
run "/api/nep_aki/st" '{"creatinine":2.5,"baseline_creatinine":1.0,"urine_output_ml_kg_hr":0.5,"stage":"injury","contrast_exposure":false}' "st"
