run "/api/nep_aki/neph" '{"aminoglycoside":false,"vancomycin":false,"nsaid":false,"contrast":true,"dose_adjusted":true}' "neph"
run "/api/nep_aki/rrt" '{"urgent_indications":false,"refractory_acidosis":false,"refractory_hyperkalemia":false,"fluid_overload_refractory":false,"uremic_complications":false}' "rrt"
run "/api/nep_aki/rec" '{"last_creatinine":1.4,"dialysis_dependent":false,"recovery_started":true,"followup_planned":true}' "rec"
echo "=== 104 GN ==="
run "/api/nep_gn/pres" '{"syndrome":"nephritic","hematuria":true,"dysmorphic_rbc":true,"rbc_casts":true,"proteinuria_24h":1500}' "pres"
