run "/api/nep_gn/tx" '{"referred":true,"workup_complete":false,"live_donor_evaluation":false,"listed":false,"scheduled":false}' "tx"
echo "=== 105 HTN ==="
run "/api/nep_htn/class" '{"sbp":135,"dbp":85,"stage":"stage_1","renovascular_suspected":false}' "class"
run "/api/nep_htn/sec" '{"renal_artery_stenosis":false,"primary_aldosteronism":false,"cushing":false,"pheo":false,"workup_initiated":false}' "sec"
run "/api/nep_htn/tx" '{"lifestyle":true,"ace_inhibitor":true,"ARB":false,"ccb":true,"diuretic":true,"target_met":true}' "tx"
run "/api/nep_htn/elec" '{"sodium":140,"potassium":4.0,"chloride":100,"bicarb":24,"magnesium":2.0,"corrected":true}' "elec"
