echo "=== 106 PED ==="
run "/api/nep_ped/uti" '{"type":"cystitis","febrile":false,"imaging_done":false,"prophylaxis":false,"age_months":36}' "uti"
run "/api/nep_ped/vur" '{"grade":"ii","bilateral":false,"prophylaxis":true,"surgical_referral":false,"followup":true}' "vur"
run "/api/nep_ped/ns" '{"steroid_responsive":true,"steroid_dependent":false,"steroid_resistant":false,"frequent_relapser":false,"biopsy_needed":false,"albumin_infused":false}' "ns"
run "/api/nep_ped/hus" '{"microangiopathic_anemia":false,"schistocytes":false,"thrombocytopenia":false,"renal_impairment":false,"dialysis_needed":false,"plasmapheresis_needed":false}' "hus"
run "/api/nep_ped/gr" '{"height_z":-1.5,"weight_z":-1.0,"growth_failure":false,"nutritional_support":true,"gh_therapy":false}' "gr"
run "/api/nep_ped/tx" '{"referred":false,"workup_complete":false,"live_donor_evaluation":false,"listed":false,"scheduled":false}' "tx"
echo ""
echo "PASS=$PASS FAIL=$FAIL"